/**
 * Rampart Edge inference engine: the hand-written Rust→wasm fp32 forward of the 4-bit gate model.
 *
 * No onnxruntime-web, no SharedArrayBuffer, no threads, no cross-origin isolation. Works in a window, a
 * Worker, Bun and Node. The wasm is inlined (`ENGINE_WASM_BASE64`, generated by `scripts/build-engine.ts`) so
 * consumers need no extra fetch or path configuration; the weights (`model/model.rmpw`) are passed in as bytes.
 */
import { ENGINE_WASM_BASE64 } from "./engine-wasm";

export { ENGINE_WASM_BASE64 };

export type EngineOutput = {
  readonly gateLogit: number;
  /** `n * 19` token logits, row-major. A copy, not a view into wasm memory. */
  readonly tokenLogits: Float32Array;
};

export type GateEngine = {
  /** Synchronous forward. `1 <= n <= 384`; throws `EngineError("range")` or `EngineError("numeric")`. */
  run(inputIds: ArrayLike<number>, attentionMask?: ArrayLike<number>): EngineOutput;
  readonly memoryPages: number;
  readonly loadMs: number;
};

export type EngineErrorStage = "wasm" | "format" | "integrity" | "init" | "range" | "numeric";

export class EngineError extends Error {
  readonly stage: EngineErrorStage;
  constructor(stage: EngineErrorStage, message: string) {
    super(message);
    this.name = "EngineError";
    this.stage = stage;
  }
}

export type WeightHeader = {
  version: number;
  hidden: number;
  ffn: number;
  heads: number;
  layers: number;
  vocab: number;
  rank: number;
  maxPos: number;
  labels: number;
  tensors: number;
};

/** Shape the engine wasm was compiled for; `createEngine` rejects anything else before touching the wasm. */
export const ENGINE_SHAPE: Readonly<WeightHeader> = Object.freeze({
  version: 1,
  hidden: 256,
  ffn: 1024,
  heads: 8,
  layers: 4,
  vocab: 23910,
  rank: 48,
  maxPos: 384,
  labels: 19,
  tensors: 42,
});

export const MAX_TOKENS = ENGINE_SHAPE.maxPos;
export const NUM_LABELS = ENGINE_SHAPE.labels;

const MAGIC = 0x5750_4d52; // "RMPW" little-endian
const FIXED_HEADER_BYTES = 76;
const TABLE_ENTRY_BYTES = 20;
const HEADER_BYTES = (FIXED_HEADER_BYTES + 42 * TABLE_ENTRY_BYTES + 15) & ~15; // 928

/** `init` return codes of the wasm (engine/src/format.rs `code`). */
const INIT_CODES: Readonly<Record<number, { stage: EngineErrorStage; message: string }>> = {
  1: { stage: "init", message: "engine already initialised" },
  2: { stage: "init", message: "weight buffer is not inside the engine arena" },
  3: { stage: "format", message: "bad magic" },
  4: { stage: "format", message: "unsupported weight format version" },
  5: { stage: "format", message: "weight shape does not match the engine" },
  6: { stage: "format", message: "malformed tensor table" },
  7: { stage: "integrity", message: "payload sha256 mismatch" },
  8: { stage: "init", message: "engine arena exhausted" },
};

type EngineExports = {
  memory: WebAssembly.Memory;
  arena_alloc(bytes: number): number;
  init(ptr: number, len: number): number;
  ids_ptr(): number;
  mask_ptr(): number;
  tok_ptr(): number;
  forward(n: number): number;
  version(): number;
};

const now = (): number => (typeof performance !== "undefined" ? performance.now() : Date.now());

/** Parse and validate the fixed header fields. Throws `EngineError("format")`. */
export function parseWeightHeader(weights: Uint8Array): WeightHeader {
  if (weights.byteLength < HEADER_BYTES) {
    throw new EngineError("format", `weights too short: ${weights.byteLength} < ${HEADER_BYTES} bytes`);
  }
  const view = new DataView(weights.buffer, weights.byteOffset, weights.byteLength);
  if (view.getUint32(0, true) !== MAGIC) throw new EngineError("format", "bad magic (expected RMPW)");
  const header: WeightHeader = {
    version: view.getUint32(4, true),
    hidden: view.getUint32(8, true),
    ffn: view.getUint32(12, true),
    heads: view.getUint32(16, true),
    layers: view.getUint32(20, true),
    vocab: view.getUint32(24, true),
    rank: view.getUint32(28, true),
    maxPos: view.getUint32(32, true),
    labels: view.getUint32(36, true),
    tensors: view.getUint32(40, true),
  };
  if (header.version !== ENGINE_SHAPE.version) {
    throw new EngineError("format", `unsupported weight format version ${header.version}`);
  }
  for (const key of Object.keys(ENGINE_SHAPE) as (keyof WeightHeader)[]) {
    if (header[key] !== ENGINE_SHAPE[key]) {
      throw new EngineError("format", `weight ${key}=${header[key]} does not match engine ${ENGINE_SHAPE[key]}`);
    }
  }
  return header;
}

/** The 32-byte payload digest stored in the header, as lowercase hex. */
export function weightPayloadDigest(weights: Uint8Array): string {
  parseWeightHeader(weights);
  let hex = "";
  for (let i = 44; i < 76; i++) hex += weights[i]!.toString(16).padStart(2, "0");
  return hex;
}

/** Decode `ENGINE_WASM_BASE64` to bytes (fresh copy each call). */
export function engineWasmBytes(): Uint8Array {
  return base64ToBytes(ENGINE_WASM_BASE64);
}

function base64ToBytes(b64: string): Uint8Array {
  if (typeof Buffer !== "undefined" && typeof Buffer.from === "function") {
    const buf = Buffer.from(b64, "base64");
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength).slice();
  }
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function compile(wasm: BufferSource | WebAssembly.Module): Promise<WebAssembly.Module> {
  if (wasm instanceof WebAssembly.Module) return wasm;
  try {
    return await WebAssembly.compile(wasm);
  } catch (e) {
    throw new EngineError("wasm", `engine wasm failed to compile: ${e instanceof Error ? e.message : String(e)}`);
  }
}

function instantiate(module: WebAssembly.Module): EngineExports {
  if (WebAssembly.Module.imports(module).length !== 0) {
    throw new EngineError("wasm", "engine wasm must not import anything");
  }
  let instance: WebAssembly.Instance;
  try {
    instance = new WebAssembly.Instance(module, {});
  } catch (e) {
    throw new EngineError("wasm", `engine wasm failed to instantiate: ${e instanceof Error ? e.message : String(e)}`);
  }
  const ex = instance.exports as Partial<Record<keyof EngineExports, unknown>>;
  const required: (keyof EngineExports)[] = ["memory", "arena_alloc", "init", "ids_ptr", "mask_ptr", "tok_ptr", "forward", "version"];
  for (const name of required) {
    const ok = name === "memory" ? ex[name] instanceof WebAssembly.Memory : typeof ex[name] === "function";
    if (!ok) throw new EngineError("wasm", `engine wasm is missing export ${name}`);
  }
  return ex as EngineExports;
}

/**
 * Compile (or reuse a precompiled module), instantiate, validate the weight header, copy the weights into the
 * engine arena and run the wasm-side validation (every header field, tensor table, payload sha256).
 */
export async function createEngine(wasm: BufferSource | WebAssembly.Module, weights: Uint8Array): Promise<GateEngine> {
  const t0 = now();
  parseWeightHeader(weights);
  const module = await compile(wasm);
  const ex = instantiate(module);
  if (ex.version() >>> 16 !== 3) throw new EngineError("wasm", `unexpected engine version ${ex.version()}`);

  const ptr = ex.arena_alloc(weights.byteLength);
  if (ptr === 0) throw new EngineError("init", "engine arena exhausted");
  new Uint8Array(ex.memory.buffer, ptr, weights.byteLength).set(weights);
  const rc = ex.init(ptr, weights.byteLength);
  if (rc !== 0) {
    const known = INIT_CODES[rc];
    throw new EngineError(known?.stage ?? "init", `${known?.message ?? "engine init failed"} (code ${rc})`);
  }
  const idsPtr = ex.ids_ptr();
  const maskPtr = ex.mask_ptr();
  const tokPtr = ex.tok_ptr();
  if (idsPtr === 0 || maskPtr === 0 || tokPtr === 0) throw new EngineError("init", "engine buffers unavailable");
  const loadMs = now() - t0;
  const vocab = ENGINE_SHAPE.vocab;

  const run = (inputIds: ArrayLike<number>, attentionMask?: ArrayLike<number>): EngineOutput => {
    const n = inputIds.length;
    if (!Number.isInteger(n) || n < 1 || n > MAX_TOKENS) {
      throw new EngineError("range", `sequence length ${n} outside 1..${MAX_TOKENS}`);
    }
    if (attentionMask !== undefined && attentionMask.length !== n) {
      throw new EngineError("range", `attention mask length ${attentionMask.length} != ${n}`);
    }
    // The buffer may have been detached if memory grew; re-create the views on every call (cheap).
    const ids = new Int32Array(ex.memory.buffer, idsPtr, n);
    const mask = new Int32Array(ex.memory.buffer, maskPtr, n);
    for (let i = 0; i < n; i++) {
      const id = Number(inputIds[i]);
      if (!Number.isInteger(id) || id < 0 || id >= vocab) {
        throw new EngineError("range", `token id ${String(inputIds[i])} at ${i} outside 0..${vocab - 1}`);
      }
      ids[i] = id;
      mask[i] = attentionMask === undefined ? 1 : Number(attentionMask[i]) ? 1 : 0;
    }
    const gateLogit = ex.forward(n);
    if (!Number.isFinite(gateLogit)) throw new EngineError("numeric", "engine returned a non-finite gate logit");
    const tokenLogits = new Float32Array(ex.memory.buffer, tokPtr, n * NUM_LABELS).slice();
    return { gateLogit, tokenLogits };
  };

  return {
    run,
    loadMs,
    get memoryPages(): number {
      return ex.memory.buffer.byteLength / 65536;
    },
  };
}
